"""Optional nowrap reporting preserves classifications, locations and generated bytes."""
from tests.selfhost_build_double import build_all
from tests.selfhost_lsp_double import leaf_compilers
from tests.support import ROOT, compiler  # noqa: F401

SOURCE = '''W:type=int32<overflow='wrap'>
bump=(x:W):>W=>x+1
cast=(x:int64):>W=>W(x)
main=()=>{
    let x=cast(args().length)
    printl(bump(x))
}
'''


def test_exact_measure_matches_twin(compiler, tmp_path, monkeypatch):
    source = tmp_path / 'measure.dewy'
    source.write_text(SOURCE)
    monkeypatch.setenv('DEWY_CORE_LIB', str(ROOT / 'lib'))
    dewy, jo = leaf_compilers(compiler, tmp_path, ('exact_measure',))
    monkeypatch.setenv('DEWY_NOWRAP_MEASURE', '1')
    expected = build_all(jo, tmp_path, 'jo', [source])
    got = build_all(dewy, tmp_path, 'dewy', [source])
    assert got == expected
    assert got[0][2] == 0, got[0][:5]
    assert '\tok\twrap\tplus\t' in got[0][4]
    assert '\tok\texplicit\teof\t' in got[0][4]
    assert '\tbump\n' in got[0][4] and '\tcast\n' in got[0][4]
